  ($str$Chemical Etching$str$, 2107),
  ($str$Cooling$str$, 2108),
  ($str$Drying$str$, 2109),
  ($str$Flash Fire De-Waxing$str$, 2110),
  ($str$Knockout$str$, 2111),
  ($str$Metal Pouring$str$, 2112),
  ($str$Mold Burnout$str$, 2113),
  ($str$Mold Preheating$str$, 2114),
  ($str$No Cost Feature$str$, 2115),
  ($str$Primary Sand Coating$str$, 2116),
  ($str$Primary Slurry Dipping$str$, 2117),
  ($str$Robotic Assist$str$, 2118),
  ($str$Secondary Sand Coating$str$, 2119),
  ($str$Secondary Slurry Dipping$str$, 2120),
  ($str$Soluble Wax Core Making$str$, 2121),
  ($str$Soluble Wax Leaching$str$, 2122),
  ($str$Steam Autoclave De-Waxing$str$, 2123),
  ($str$Wax Pattern Molding$str$, 2124)
) AS v(name, display_order)
  ON pt.process_group = $str$Casting Investment$str$ AND pt.process_name = v.name
WHERE NOT EXISTS (
  SELECT 1 FROM process_calculator_mappings m WHERE m.process_group = $str$Casting Investment$str$ AND m.operation = v.name
)
ON CONFLICT (process_group, process_route, operation) DO NOTHING;

COMMIT;

